"use client";

import { Download, FileSpreadsheet, Loader2, Upload } from "lucide-react";
import { useRef, useState } from "react";
import { StatusBadge } from "@/components/feedback/badges";
import { Button } from "@/components/ui/button";
import { DialogContent, DialogDescription, DialogTitle } from "@/components/ui/overlays";
import { adminApi, type UserImportItem, type UserImportResult } from "@/lib/api";
import { cn } from "@/lib/utils/cn";

const ACCEPT = ".xlsx,.xlsm,.xlsb,.csv";
/** generated by the backend from the same columns the import reads */
const TEMPLATE_HREF = "/api/v1/users/import/template.xlsx";
/** the file format shown before a file is chosen (required columns first) */
const FORMAT: { col: string; required?: boolean; example: string }[] = [
  { col: "Name", required: true, example: "Ravi Kumar" },
  { col: "Email", required: true, example: "ravi@pratap.co.in" },
  { col: "Password", example: "Ravi@Pratap2026" },
  { col: "Circle", example: "Rajasthan" },
  { col: "BA", example: "Jaipur" },
  { col: "District", example: "" },
  { col: "Block", example: "" },
  { col: "GP", example: "" },
];
const STATUS: Record<UserImportItem["status"], { tone: "good" | "neutral" | "warning"; label: string }> = {
  NEW: { tone: "good", label: "New" },
  CREATED: { tone: "good", label: "Created" },
  EXISTS: { tone: "neutral", label: "Already a user" },
  SKIPPED: { tone: "warning", label: "Skipped" },
};

/** Bulk import: pick an Excel / CSV file with Name and Email columns -> preview -> create the new Viewer accounts. */
export function ImportUsersDialog({ onDone }: { onDone: (msg: string) => void }) {
  const input = useRef<HTMLInputElement>(null);
  const [file, setFile] = useState<File | null>(null);
  const [result, setResult] = useState<UserImportResult | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const run = async (f: File, dryRun: boolean) => {
    setBusy(true);
    setError(null);
    try {
      const r = await adminApi.importUsers(f, dryRun);
      if (dryRun) setResult(r);
      else {
        const temp = r.temporaryCount ?? r.created;
        onDone(
          `${r.created} user(s) created from ${f.name}` +
            (temp === 0 ? " with the passwords from the file." : temp === r.created ? ` with the temporary password ${r.temporaryPassword}.` : ` – ${temp} without a password in the file got the temporary password ${r.temporaryPassword}.`),
        );
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Import failed");
    } finally {
      setBusy(false);
    }
  };

  const pick = (f: File | undefined) => {
    if (!f) return;
    setFile(f);
    setResult(null);
    void run(f, true);
  };

  const createButton = (
    <Button type="button" variant="primary" disabled={!file || !result || result.new === 0 || busy} onClick={() => file && void run(file, false)}>
      {busy && result && <Loader2 className="animate-spin" />} Create {result?.new ?? 0} user{result?.new === 1 ? "" : "s"}
    </Button>
  );

  return (
    <DialogContent className="top-[4vh] flex max-h-[92vh] max-w-3xl flex-col">
      <div className="flex min-h-0 flex-1 flex-col gap-4 p-5">
        <div className="shrink-0 pr-8">
          <DialogTitle className="text-base font-bold">Import users</DialogTitle>
          <DialogDescription className="text-[0.8125rem] text-muted-foreground">
            Excel (.xlsx, .xlsm, .xlsb) or CSV. Every new e-mail address becomes a <b>Viewer</b>; existing users are not changed.
          </DialogDescription>
        </div>

        {!result && (
          <div className="shrink-0 space-y-2 rounded-lg border border-border bg-muted/30 p-3">
            <div className="flex flex-wrap items-center justify-between gap-2">
              <span className="text-xs font-semibold">File format</span>
              <a href={TEMPLATE_HREF} download className="inline-flex items-center gap-1 text-xs font-medium text-primary hover:underline">
                <Download className="size-3.5" aria-hidden /> Download template (.xlsx)
              </a>
            </div>
            <div className="overflow-x-auto rounded-md border border-border bg-card">
              <table className="w-full min-w-[40rem] text-xs">
                <thead>
                  <tr className="border-b border-border">
                    {FORMAT.map((f) => (
                      <th key={f.col} scope="col" className={cn("px-2 py-1.5 text-left font-semibold", f.required ? "text-primary" : "text-muted-foreground")}>
                        {f.col}
                        {f.required && " *"}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    {FORMAT.map((f) => (
                      <td key={f.col} className="px-2 py-1.5 italic text-muted-foreground">
                        {f.example || "—"}
                      </td>
                    ))}
                  </tr>
                </tbody>
              </table>
            </div>
            <ul className="list-disc space-y-0.5 pl-4 text-[0.75rem] text-muted-foreground">
              <li>
                <b>*</b> Name and Email are required; every other column is optional and can be deleted.
              </li>
              <li>Password: at least 12 characters with 3 of lower-case, upper-case, digits, symbols (a weak one skips the row). Empty = the temporary password.</li>
              <li>
                Circle / BA / District / Block / GP decide what the user sees – the most specific filled column counts (Rajasthan + Jaipur = only Jaipur BA). Several
                values: separate with commas. All empty = every circle.
              </li>
              <li>A name not in the current data skips the row – the preview shows why before anything is created.</li>
              <li>
                How to fill: two places in one cell with a comma (<b>Barmer, Jaisalmer</b>) · BA spelt as on the dashboard · when a District is filled, leave BA
                empty · one complete e-mail per row, without spaces, each e-mail only once. The template&apos;s Instructions sheet has the details.
              </li>
            </ul>
          </div>
        )}

        <div className="flex shrink-0 flex-wrap items-center gap-3 rounded-lg border border-dashed border-border p-4">
          <FileSpreadsheet className="size-5 text-primary" />
          <span className="min-w-0 flex-1 truncate text-sm">{file ? file.name : "No file selected"}</span>
          <input
            ref={input}
            type="file"
            accept={ACCEPT}
            className="hidden"
            onChange={(e) => {
              pick(e.target.files?.[0]);
              e.target.value = "";
            }}
          />
          <Button type="button" variant="outline" onClick={() => input.current?.click()} disabled={busy}>
            <Upload /> {file ? "Choose another file" : "Choose file"}
          </Button>
        </div>

        {busy && !result && (
          <p className="flex shrink-0 items-center gap-2 text-sm text-muted-foreground">
            <Loader2 className="size-4 animate-spin" /> Reading the file…
          </p>
        )}

        {result && (
          <>
            <div className="flex shrink-0 flex-wrap items-center gap-2 text-xs">
              <Count label="Rows" value={result.total} />
              <Count label="Will be created" value={result.new} tone="good" />
              <Count label="Already users" value={result.exists} />
              <Count label="Skipped" value={result.skipped} tone={result.skipped ? "warning" : undefined} />
              <span className="ml-auto">{createButton}</span>
            </div>
            {result.new > 0 && (result.temporaryCount ?? result.new) > 0 && (
              <p className="shrink-0 text-[0.8125rem] text-muted-foreground">
                {result.withPasswords ? `${result.temporaryCount} new user(s) without a password in the file get` : "Temporary password for the new users:"}{" "}
                <code className="rounded bg-muted px-1.5 py-0.5 font-semibold text-foreground">{result.temporaryPassword}</code> – ask them to change it after
                signing in (account menu or Settings → Change password).
              </p>
            )}
            {result.new > 0 && result.withPasswords && result.temporaryCount === 0 && (
              <p className="shrink-0 text-[0.8125rem] text-muted-foreground">Every new user signs in with the password given in the file.</p>
            )}
            <div className="min-h-[8.75rem] flex-1 overflow-auto rounded-lg border border-border">
              <table className="w-full min-w-[35rem] text-sm">
                <thead className="sticky top-0 bg-card">
                  <tr className="border-b border-border text-left text-xs text-muted-foreground">
                    {["Row", "Name", "Email", ...(result.withAreas ? ["Areas"] : []), ...(result.withPasswords ? ["Password"] : []), "Result"].map((c) => (
                      <th key={c} scope="col" className="px-3 py-2 font-medium">
                        {c}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {result.items.map((it) => (
                    <tr key={`${it.row}:${it.email}`} className="border-b border-border/60 last:border-0">
                      <td className="px-3 py-1.5 text-muted-foreground">{it.row}</td>
                      <td className="px-3 py-1.5">{it.name || "—"}</td>
                      <td className="px-3 py-1.5 text-muted-foreground">{it.email || "—"}</td>
                      {result.withAreas && (
                        <td className="px-3 py-1.5 text-xs">
                          {it.areas?.length ? it.areas.join(" · ") : it.status === "SKIPPED" ? "—" : <span className="text-warning-text">Every circle</span>}
                        </td>
                      )}
                      {result.withPasswords && <td className="px-3 py-1.5 text-xs text-muted-foreground">{it.password === "FILE" ? "From the file" : "Temporary"}</td>}
                      <td className="px-3 py-1.5">
                        <StatusBadge tone={STATUS[it.status].tone}>{STATUS[it.status].label}</StatusBadge>
                        {it.reason && it.status === "SKIPPED" && <span className="ml-2 text-xs text-warning-text">{it.reason}</span>}
                      </td>
                    </tr>
                  ))}
                  {!result.items.length && (
                    <tr>
                      <td colSpan={4 + (result.withAreas ? 1 : 0) + (result.withPasswords ? 1 : 0)} className="px-3 py-4 text-center text-muted-foreground">
                        No user rows found under the header.
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </>
        )}

        {error && <p className="shrink-0 text-sm text-critical-text">{error}</p>}
        <div className="flex shrink-0 items-center justify-end gap-2 border-t border-border pt-3">
          {result && result.new === 0 && <span className="mr-auto text-xs text-muted-foreground">No new e-mail address in this file – nothing to create.</span>}
          {createButton}
        </div>
      </div>
    </DialogContent>
  );
}

function Count({ label, value, tone }: { label: string; value: number; tone?: "good" | "warning" }) {
  return (
    <span
      className={cn(
        "rounded-md border px-2.5 py-1",
        tone === "good" ? "border-good/30 bg-good-soft text-good-text" : tone === "warning" ? "border-warning/30 bg-warning-soft text-warning-text" : "border-border text-muted-foreground",
      )}
    >
      {label}: <b>{value}</b>
    </span>
  );
}
